// ---------------------------------------------------------------------------
// Primitives
// ---------------------------------------------------------------------------

export type DsTheme = 'Light' | 'Dark';
export type DsCellState = 'Default' | 'Hover' | 'Selected' | 'Selected + Hover';
export type DsAlertType = 'none' | 'info' | 'warning' | 'danger' | 'success';

// ---------------------------------------------------------------------------
// Semantic Color (cell-level content color, distinct from row-level alertType)
// ---------------------------------------------------------------------------

export type SemanticColor
  = | 'primary' // Blue
    | 'success' // Green
    | 'warning' // Orange
    | 'danger' // Red
    | 'info' // Cyan
    | 'error' // Red (alias for danger)
    | 'pending'; // Orange (alias for warning)

export const semanticColorMap: Record<SemanticColor, string> = {
  primary: 'var(--color-primary-default)',
  success: 'var(--color-success-default)',
  warning: 'var(--color-warning-default)',
  danger: 'var(--color-danger-default)',
  info: 'var(--color-info-default)',
  error: 'var(--color-danger-default)', // Alias
  pending: 'var(--color-warning-default)', // Alias
};

// ---------------------------------------------------------------------------
// Semantic auto-detection helpers
// ---------------------------------------------------------------------------

export type TrendDirection = 'up' | 'down';

export const trendColorMap: Record<TrendDirection, string> = {
  up: 'var(--color-success-default)',
  down: 'var(--color-danger-default)',
};

export const statusValueColorMap: Record<string, SemanticColor> = {
  // Success states
  active: 'success',
  success: 'success',
  completed: 'success',
  online: 'success',

  // Warning states
  pending: 'warning',
  warning: 'warning',
  paused: 'warning',
  idle: 'warning',

  // Danger states
  inactive: 'danger',
  error: 'danger',
  failed: 'danger',
  offline: 'danger',

  // Info states
  info: 'info',
};

export const progressValueColorMap = {
  getColor: (value: number): SemanticColor => {
    if (value >= 75) return 'success'; // Green:  75-100%
    if (value >= 50) return 'warning'; // Orange: 50-74%
    return 'danger'; // Red:    0-49%
  },
};

// ---------------------------------------------------------------------------
// Cell type union
// ---------------------------------------------------------------------------

export type DsBodyCellType
  = | 'Leading cell'
    | 'Text'
    | 'Text + 2nd text'
    | 'Progress'
    | 'Sparkline'
    | 'Rating stars'
    | 'Toggle'
    | 'Actions'
    | 'Trend'
    | 'Percentage'
    | 'Status'
    | 'Avatar'
    | 'List';

// ---------------------------------------------------------------------------
// Chrome (row-level decoration shared by every cell type)
// ---------------------------------------------------------------------------

export interface BodyCellChrome {
  theme?: DsTheme
  state?: DsCellState
  zebra?: boolean
  alertType?: DsAlertType
  dense?: boolean
}

// ---------------------------------------------------------------------------
// LeadingCell — split into content sub-type for composability
// ---------------------------------------------------------------------------

/** Optional rich content slots within a Leading cell. */
export interface LeadingCellContent {
  checkbox?: { checked: boolean, disabled?: boolean }
  profile?: { initials?: string, src?: string }
  leftIcon?: string
  rightIcon?: string
  sparkline?: {
    values: Array<number>
    variant?: 'positive' | 'negative' | 'neutral'
    showArea?: boolean
    showDots?: boolean
  }
  actions?: Array<{
    id: string
    text?: string
    icon?: string
    disabled?: boolean
  }>
}

/** Leading cell — backwards-compatible with the original flat shape. */
export type LeadingCell = BodyCellChrome
  & LeadingCellContent & {
    type: 'Leading cell'
    text: string
    secondText?: string
  };

// ---------------------------------------------------------------------------
// Existing cell types (unchanged except where specified)
// ---------------------------------------------------------------------------

export type TextCell = BodyCellChrome & {
  type: 'Text'
  text: string
};

export type Text2Cell = BodyCellChrome & {
  type: 'Text + 2nd text'
  text: string
  secondText: string
};

export type ProgressCell = BodyCellChrome & {
  type: 'Progress'
  value: number
  color?: SemanticColor
  colorOverride?: string
  /** Legacy direct CSS color — prefer color/colorOverride */
  cssColor?: string
  text?: string
};

export type SparklineCell = BodyCellChrome & {
  type: 'Sparkline'
  values: Array<number>
  variant?: 'positive' | 'negative' | 'neutral'
  showArea?: boolean
  showDots?: boolean
  color?: SemanticColor
  colorOverride?: string
};

export type RatingStarsCell = BodyCellChrome & {
  type: 'Rating stars'
  value: number // 0..5
  color?: SemanticColor
  colorOverride?: string
};

export type ToggleCell = BodyCellChrome & {
  type: 'Toggle'
  modelValue: boolean
  disabled?: boolean
};

export type ActionsCell = BodyCellChrome & {
  type: 'Actions'
  actions: Array<{
    id: string
    text?: string
    icon?: string
    disabled?: boolean
  }>
};

// ---------------------------------------------------------------------------
// New cell types migrated from TableCell.types.ts
// ---------------------------------------------------------------------------

/**
 * Trend cell — string value with auto-detected +/- direction and color.
 * e.g. value="+45.2%" → up arrow + success green
 *      value="-12.3%" → down arrow + danger red
 */
export type TrendCell = BodyCellChrome & {
  type: 'Trend'
  /** Trend value including sign prefix, e.g. "+45.2%" or "-12.3%" */
  value: string
  colorOverride?: string
};

/**
 * Percentage cell — simple numeric percentage display.
 * e.g. value=85 renders as "85%"
 */
export type PercentageCell = BodyCellChrome & {
  type: 'Percentage'
  value: number | string
};

/**
 * Status cell — semantic status display with auto-detected color.
 * e.g. value="Active" → green dot + label
 *      value="Pending" → orange dot + label
 *      value="Inactive" → red dot + label
 */
export type StatusCell = BodyCellChrome & {
  type: 'Status'
  value: string
  color?: SemanticColor
  colorOverride?: string
};

/**
 * Avatar cell — circular badge with initials/text.
 * e.g. value="JS" → badge with "JS"
 */
export type AvatarCell = BodyCellChrome & {
  type: 'Avatar'
  value: string
  colorOverride?: string
};

/**
 * List cell — displays a list of items with overflow handling.
 * Shows first N items, then "+X more" with tooltip showing remaining items.
 * e.g. items=["React", "Vue", "Angular", "Svelte"] → "React, Vue +2 more"
 */
export type ListCell = BodyCellChrome & {
  type: 'List'
  items: Array<string>
  maxVisible?: number // Default: 2
  separator?: string // Default: ", "
  color?: SemanticColor
  colorOverride?: string
};

// ---------------------------------------------------------------------------
// Master union & convenience helper
// ---------------------------------------------------------------------------

export type DsBodyCellProperties
  = | LeadingCell
    | TextCell
    | Text2Cell
    | ProgressCell
    | SparklineCell
    | RatingStarsCell
    | ToggleCell
    | ActionsCell
    | TrendCell
    | PercentageCell
    | StatusCell
    | AvatarCell
    | ListCell;

export type PropertiesFor<T extends DsBodyCellType> = Extract<
  DsBodyCellProperties,
  { type: T }
>;

/**
 * Table Filtering Type Definitions
 *
 * Provides strong typing for the table filtering system.
 * Supports text search, per-column filters, and date filtering.
 */

/**
 * Supported filter types in the table
 */
export type FilterType = 'text' | 'date' | 'dateRange' | 'custom';

/**
 * Text-based filter (substring search)
 */
export interface TextFilter {
  type: 'text'
  value: string
  columnName?: string // Undefined = search all columns
  caseSensitive?: boolean // Defaults to false
}

/**
 * Single date filter
 */
export interface DateFilter {
  type: 'date'
  columnName: string
  date: string // YYYY-MM-DD format
  operator?: 'equals' | 'before' | 'after' | 'onOrBefore' | 'onOrAfter' // Defaults to 'equals'
}

/**
 * Date range filter (inclusive on both ends)
 */
export interface DateRangeFilter {
  type: 'dateRange'
  columnName: string
  startDate: string // YYYY-MM-DD format
  endDate: string // YYYY-MM-DD format
}

/**
 * Custom filter for extensibility
 * Allows user-defined filter logic via predicate function
 */
export interface CustomFilter {
  type: 'custom'
  columnName?: string
  predicate: (value: unknown) => boolean
}

/**
 * Union of all filter types
 */
export type FilterValue
  = | TextFilter
    | DateFilter
    | DateRangeFilter
    | CustomFilter;

/**
 * State of a single filter
 */
export interface FilterState {
  id: string // Unique identifier for the filter
  filter: FilterValue
  active: boolean
  createdAt: number // Timestamp for ordering
}

/**
 * Map of active filters by column name
 * structure: { columnName: { id: FilterState, ... }, ... }
 */
export type ActiveFiltersRecord = Record<string, Array<FilterState>>;

/**
 * Summary of active filters
 */
export interface ActiveFiltersSummary {
  byColumn: Record<string, Array<FilterValue>> // Filters by column
  all: Array<FilterValue> // All active filters
  count: number // Total count of active filters
}

/**
 * Options for useTableFiltering composable
 */
export interface UseTableFilteringOptions {
  caseSensitiveByDefault?: boolean
  dateFormat?: string // Defaults to YYYY-MM-DD
}

import { computed, ref, watch, type Ref } from 'vue';
import type { FilterField } from '../reusable-components/types/filter-field';
import type { TableProperties } from './table.types';

type AdvancedFilterProperties<T extends Record<string, unknown>> = Pick<
  TableProperties<T>,
  | 'useAdvancedFilter'
  | 'advancedFilterConfig'
  | 'columns'
  | 'advancedFilterStore'
>;

/**
 * Checks if a value is considered empty for filtering purposes
 * @param value The value to check
 * @returns true if the value is empty, false otherwise
 */
function isEmpty(value: unknown): boolean {
  if (value === null || value === undefined || value === '' || value === false)
    return true;
  if (Array.isArray(value) && value.length === 0) return true;
  return false;
}

/**
 * Converts a value to a primitive string representation
 * @param value The value to convert
 * @returns The string representation of the value
 */
function toPrimitive(value: unknown): string {
  if (value === null || value === undefined) return '';
  if (typeof value === 'object') return JSON.stringify(value);
  return String(value as string | number | boolean);
}

/**
 * Resolves the label for a dropdown value based on available options
 * @param label The original value/label selected
 * @param options The available options to resolve against
 * @returns The resolved option label or the original value if not found
 */
function resolveDropdownValue(
  label: unknown,
  options: Array<Record<string, unknown>>,
): unknown {
  if (label === null || label === undefined || label === '') return label;
  const match = options.find(o => o.label === label);
  return match === undefined ? label : match.value;
}

/**
 * @param rows - Reactive rows reference
 * @param properties - Filter properties
 * @returns Filtered rows and helper methods
 */
export function useAdvancedFilter<T extends Record<string, unknown>>(
  rows: Ref<Array<T>>,
  properties: AdvancedFilterProperties<T>,
) {
  const filterStore = ref<Record<string, unknown>>(
    properties.advancedFilterStore ?? {},
  );

  watch(
    () => properties.advancedFilterStore,
    (newValue) => {
      if (newValue !== undefined && newValue !== null)
        filterStore.value = newValue;
    },
    { deep: true },
  );

  const searchableColumnNames = computed(() =>
    (properties.advancedFilterConfig ?? [])
      .filter(f => f.type === 'text' && f.modelKey !== 'searchText')
      .map(f => f.modelKey),
  );

  /**
   * @param record - Source record to read from
   * @param key - Key to resolve within the record
   * @returns Value for the key when present
   */
  function getRecordValue(
    record: Record<string, unknown>,
    key: string,
  ): unknown {
    const entry = Object.entries(record).find(([k]) => k === key);
    return entry?.[1];
  }

  /**
   * Checks if a row matches the global search text.
   * @param row - Row to check
   * @param searchText - Search text to match
   * @returns True when the row matches the search
   */
  function matchesGlobalSearch(row: T, searchText: string): boolean {
    const needle = searchText.toLowerCase();
    const fields
      = searchableColumnNames.value.length > 0
        ? searchableColumnNames.value
        : properties.columns.map(c => c.name);

    for (const fieldName of fields) {
      const col = properties.columns.find(c => c.name === fieldName);
      const rowRecord = row as Record<string, unknown>;
      let value: unknown;
      if (col === undefined) {
        value = getRecordValue(rowRecord, fieldName);
      }
      else if (typeof col.field === 'function') {
        value = col.field(row);
      }
      else {
        value = getRecordValue(rowRecord, String(col.field));
      }

      if (typeof value === 'string' && value.toLowerCase().includes(needle))
        return true;
      if (Array.isArray(value)) {
        const found = value.some(item =>
          String(item).toLowerCase().includes(needle),
        );
        if (found) return true;
      }
    }
    return false;
  }

  /**
   * Checks if a row value matches a dropdown filter.
   * @param rowValue - Value from the row
   * @param filterValue - Selected filter value(s)
   * @param config - Filter field configuration
   * @returns True when the row value matches the filter
   */
  function matchesDropdownField(
    rowValue: unknown,
    filterValue: unknown,
    config: FilterField,
  ): boolean {
    const rawOptions
      = typeof config.options === 'function'
        ? config.options()
        : (config.options ?? []);
    const options = rawOptions as Array<Record<string, unknown>>;

    if (Array.isArray(filterValue)) {
      if (filterValue.length === 0) return true;
      const resolved = filterValue.map(label =>
        resolveDropdownValue(label, options),
      );
      return resolved.some(v => toPrimitive(v) === toPrimitive(rowValue));
    }

    return (
      toPrimitive(rowValue)
      === toPrimitive(resolveDropdownValue(filterValue, options))
    );
  }

  /**
   * Checks if a single field matches a filter.
   * @param row - Row being evaluated
   * @param key - Field key to check
   * @param rawValue - Raw filter value
   * @param config - Filter field configuration
   * @returns True when the row field matches the filter
   */
  function matchesSingleField(
    row: T,
    key: string,
    rawValue: unknown,
    config: FilterField | undefined,
  ): boolean {
    const rowValue = getRecordValue(row as Record<string, unknown>, key);

    let filterValue = rawValue;
    if (
      rawValue !== null
      && rawValue !== undefined
      && typeof rawValue === 'object'
      && 'value' in rawValue
    ) {
      filterValue = (rawValue as Record<string, unknown>).value;
    }

    if (config !== undefined && typeof config.customFilter === 'function') {
      return config.customFilter(rowValue, filterValue, row);
    }

    if (config?.type === 'dropdown') {
      return matchesDropdownField(rowValue, filterValue, config);
    }

    if (Array.isArray(filterValue)) {
      if (filterValue.length === 0) return true;
      return filterValue.some(v => toPrimitive(v) === toPrimitive(rowValue));
    }

    if (config?.type === 'number') {
      const numberValue = Number(filterValue);
      if (
        !Number.isNaN(numberValue)
        && typeof rowValue === 'number'
        && rowValue < numberValue
      )
        return false;
      return true;
    }

    if (config?.type === 'text') {
      if (rowValue === null || rowValue === undefined) return false;
      return toPrimitive(rowValue)
        .toLowerCase()
        .includes(toPrimitive(filterValue).toLowerCase());
    }

    return toPrimitive(rowValue) === toPrimitive(filterValue);
  }

  const filteredRows = computed<Array<T>>(() => {
    if (properties.useAdvancedFilter !== true) return rows.value;

    const store = filterStore.value;
    const hasFilters = Object.entries(store).some(
      ([k, v]) => k !== 'resetSelect' && !isEmpty(v),
    );

    if (!hasFilters) return rows.value;

    return rows.value.filter((row: T) => {
      const searchText = store.searchText;
      if (
        typeof searchText === 'string'
        && searchText !== ''
        && !matchesGlobalSearch(row, searchText)
      ) {
        return false;
      }

      for (const [key, rawValue] of Object.entries(store)) {
        if (key === 'resetSelect' || key === 'searchText' || isEmpty(rawValue))
          continue;

        const config = properties.advancedFilterConfig?.find(
          f => f.modelKey === key,
        );
        if (!matchesSingleField(row, key, rawValue, config)) return false;
      }

      return true;
    });
  });

  /**
   *
   */
  function resetFilters(): void {
    const reset: Record<string, unknown> = { resetSelect: false };
    for (const f of properties.advancedFilterConfig ?? []) {
      if (f.type === 'dropdown' || f.type === 'tree-select') {
        reset[f.modelKey] = f.multiSelect === true ? [] : '';
      }
      else if (f.type === 'number') {
        reset[f.modelKey] = null;
      }
      else {
        reset[f.modelKey] = '';
      }
    }
    filterStore.value = reset;
  }

  return { filterStore, filteredRows, resetFilters };
}

import { computed, ref, type Ref } from 'vue';
import type { FilterField } from '../reusable-components/types/filter-field';
import type { TableColumn } from './table.types';

export interface UseAutoFilterConfigOptions {
  exclude?: Array<string>
}

export interface UseAutoFilterConfigResult {
  filterConfig: Array<FilterField>
  storeRef: Ref<Record<string, unknown>>
  resetStore: () => void
}

/**
 * Checks if a value matches a date pattern.
 * @param value - The value to check
 * @returns True if the value is a date string
 */
function isDatePattern(value: unknown): boolean {
  if (typeof value !== 'string') return false;
  if (/^\d{4}-\d{2}-\d{2}/.test(value)) return true;
  if (/^\d{2}\/\d{2}\/\d{4}$/.test(value)) return true;
  return false;
}

/**
 * @param columns - Table column definitions
 * @param rows - Row data
 * @param options - Config options
 * @returns Filter configuration and store management
 */
export function useAutoFilterConfig<T extends Record<string, unknown>>(
  columns: Array<TableColumn<T>>,
  rows: Ref<Array<T>> | Array<T>,
  options: UseAutoFilterConfigOptions = {},
): UseAutoFilterConfigResult {
  const { exclude = ['id', 'avatar'] } = options;
  const rowsArray = resolveRowsArray(rows);

  const storeReference = ref<Record<string, unknown>>({
    searchText: null,
    resetSelect: false,
  });

  /**
   * Collects unique values from a column for filter options.
   * @param column - Column definition to collect options for
   * @returns Array of label-value option objects
   */
  function collectUniqueOptions(
    column: TableColumn<T>,
  ): Array<{ label: string, value: unknown }> {
    const seenValues = new Set<unknown>();
    const result: Array<{ label: string, value: unknown }> = [];

    for (const row of rowsArray) {
      const cellValue = getCellValue(row, column);

      if (
        cellValue !== null
        && cellValue !== undefined
        && !seenValues.has(cellValue)
      ) {
        seenValues.add(cellValue);
        let displayValue = '';
        if (column.format) {
          displayValue = column.format(cellValue, row);
        }
        else if (
          typeof cellValue === 'string'
          || typeof cellValue === 'number'
          || typeof cellValue === 'boolean'
        ) {
          displayValue = String(cellValue);
        }
        else {
          displayValue = JSON.stringify(cellValue);
        }
        result.push({ label: displayValue, value: cellValue });
      }
    }

    result.sort((a, b) => a.label.localeCompare(b.label));
    return result;
  }

  /**
   * Infers the filter type based on column configuration and data.
   * @param column - Column definition to infer filter type from
   * @returns Filter type string (text, number, date, dropdown, none)
   */
  function inferFilterType(column: TableColumn<T>): string {
    if (column.filterType === 'none') return 'none';
    if (column.filterType !== undefined) return column.filterType;

    const cellType: string | undefined
      = column.cell !== undefined
        && typeof column.cell === 'object'
        && 'type' in column.cell
        ? (Reflect.get(column.cell, 'type') as string | undefined)
        : undefined;

    if (cellType === 'Badge' || cellType === 'Status' || cellType === 'Tag')
      return 'dropdown';
    if (cellType === 'Date' || cellType === 'DateRange') return 'date';
    if (cellType === 'Currency' || cellType === 'Number') return 'number';

    const sampleValues: Array<unknown> = [];
    const valueTypes = new Set<string>();
    let dateCount = 0;

    for (const row of rowsArray) {
      const value = getCellValue(row, column);

      if (value !== null && value !== undefined) {
        sampleValues.push(value);
        valueTypes.add(typeof value);
        if (isDatePattern(value)) dateCount++;
        if (sampleValues.length >= 50) break;
      }
    }

    if (valueTypes.size === 1 && valueTypes.has('number')) return 'number';
    if (dateCount > sampleValues.length * 0.7) return 'date';

    const distinctValues = new Set(sampleValues);
    if (distinctValues.size <= 15) return 'dropdown';

    return 'text';
  }

  /**
   * Gets the cell value from a row, using column field or function.
   * @param row - Row to read from
   * @param column - Column definition to resolve
   * @returns The cell value
   */
  function getCellValue(row: T, column: TableColumn<T>): unknown {
    if (typeof column.field === 'function') {
      return column.field(row);
    }

    return row[column.field];
  }

  const filterConfig = computed<Array<FilterField>>(() => {
    const config: Array<FilterField> = [
      { modelKey: 'searchText', type: 'text', label: 'Search' },
    ];

    for (const column of columns) {
      if (exclude.includes(column.name)) continue;

      const filterType = inferFilterType(column);
      if (filterType === 'none') continue;

      const customOptions = column.filterOptions;
      const multiSelect = column.filterMultiSelect ?? false;
      const step = column.filterStep ?? 1;
      const label = `Filter by ${column.label === '' ? column.name : column.label}`;

      switch (filterType) {
        case 'dropdown': {
          config.push({
            modelKey: column.name,
            type: 'dropdown',
            label,
            multiSelect,
            options: customOptions ?? (() => collectUniqueOptions(column)),
          });
          break;
        }
        case 'number': {
          config.push({ modelKey: column.name, type: 'number', label, step });
          break;
        }
        case 'date': {
          config.push({ modelKey: column.name, type: 'date', label });
          break;
        }
        default: {
          config.push({ modelKey: column.name, type: 'text', label });
        }
      }
    }

    return config;
  });

  /**
   * Resets the filter store to default values.
   */
  function resetStore(): void {
    storeReference.value = {
      searchText: null,
      resetSelect: false,
    };
  }

  /**
   * Converts a source into a rows array.
   * @param source - Rows reference or array
   * @returns Array of rows
   */
  function resolveRowsArray(source: Ref<Array<T>> | Array<T>): Array<T> {
    if (Array.isArray(source)) {
      return [...source];
    }

    return [...source.value];
  }

  return {
    filterConfig: filterConfig.value,
    storeRef: storeReference,
    resetStore,
  };
}

import { ref, computed, onUnmounted } from 'vue';
import type { TableProperties, ResizeState } from './table.types';

/**
 * @param properties - Table properties
 * @param emit - Column resize emit function
 * @returns Object with resizing state, column widths, and resize methods
 */
export function useColumnResize<T extends Record<string, unknown>>(
  properties: TableProperties<T>,
  emit: (event: 'column-resize', columnName: string, width: number) => void,
) {
  const resizing = ref<ResizeState>({
    columnName: null,
    startX: 0,
    startWidth: 0,
  });

  const columnWidths = ref<Record<string, number>>({
    ...properties.persistedWidths,
  });

  const isResizing = computed(() => resizing.value.columnName !== null);

  /**
   * @param columnName - Column to start resizing
   * @param event - Mouse event
   */
  function startResize(columnName: string, event: MouseEvent): void {
    if (properties.resizableColumns !== true) return;

    const column = properties.columns.find(col => col.name === columnName);
    if (column === undefined || column.resizable === false) return;

    event.preventDefault();
    event.stopPropagation();

    const startWidth
      = (Reflect.get(columnWidths.value, columnName) as number | undefined)
        ?? 150;

    resizing.value = {
      columnName,
      startX: event.clientX,
      startWidth,
    };

    document.addEventListener('mousemove', handleResize);
    document.addEventListener('mouseup', stopResize);
  }

  /**
   * @param event - Mouse move event
   */
  function handleResize(event: MouseEvent): void {
    if (resizing.value.columnName === null) return;

    const { columnName, startX, startWidth } = resizing.value;
    const delta = event.clientX - startX;
    const newWidth = Math.max(
      properties.minColumnWidth ?? 80,
      startWidth + delta,
    );

    Reflect.set(columnWidths.value, columnName, newWidth);
  }

  /**
   * Stop resizing the column and emit final width
   */
  function stopResize(): void {
    if (resizing.value.columnName === null) return;

    const { columnName } = resizing.value;
    const finalWidth = Reflect.get(columnWidths.value, columnName) as
      | number
      | undefined;

    if (finalWidth !== undefined) {
      emit('column-resize', columnName, finalWidth);
    }

    resizing.value = {
      columnName: null,
      startX: 0,
      startWidth: 0,
    };

    document.removeEventListener('mousemove', handleResize);
    document.removeEventListener('mouseup', stopResize);
  }

  /**
   * @param columnName - Column name to get style for
   * @returns Column style object with width and minWidth
   */
  function getColumnStyle(columnName: string): Record<string, string> {
    const width = Reflect.get(columnWidths.value, columnName) as
      | number
      | undefined;

    if (width !== undefined) {
      return {
        width: `${width}px`,
        minWidth: `${properties.minColumnWidth ?? 80}px`,
      };
    }

    const column = properties.columns.find(col => col.name === columnName);
    if (column?.width !== undefined && column.width !== '') {
      return {
        width: column.width,
        minWidth: `${properties.minColumnWidth ?? 80}px`,
      };
    }

    return {};
  }

  onUnmounted(() => {
    document.removeEventListener('mousemove', handleResize);
    document.removeEventListener('mouseup', stopResize);
  });

  return {
    isResizing,
    columnWidths,
    startResize,
    getColumnStyle,
  };
}

import { computed, reactive, type Ref } from 'vue';
import type {
  FilterState,
  FilterValue,
  TextFilter,
  DateFilter,
  DateRangeFilter,
  CustomFilter,
  ActiveFiltersSummary,
  UseTableFilteringOptions,
} from './table-filter.types';
import type { TableColumn } from './table.types';

interface FilterStateStorage {
  byColumn: Map<string, Array<FilterState>>
  allFilters: Map<string, FilterState>
}

/**
 * Generates a unique filter identifier.
 * @returns Unique filter id string
 */
function generateFilterId(): string {
  return `filter_${Date.now()}_${Math.random().toString(36).slice(2, 11)}`;
}

/**
 * Checks if a string matches a search term.
 * @param cellValue - Cell text value to check
 * @param searchTerm - Search text to match
 * @param caseSensitive - Whether match should be case sensitive
 * @returns True when the term is found in the cell value
 */
function matchesSearchTerm(
  cellValue: string,
  searchTerm: string,
  caseSensitive: boolean,
): boolean {
  if (!caseSensitive) {
    return cellValue.toLowerCase().includes(searchTerm.toLowerCase());
  }
  return cellValue.includes(searchTerm);
}

/**
 * Converts a cell value into a string for matching.
 * @param value - Cell value to stringify
 * @returns String representation used for search matching
 */
function stringifyCellValue(value: unknown): string {
  if (value === null || value === undefined) return '';
  if (typeof value === 'string') return value;
  if (
    typeof value === 'number'
    || typeof value === 'boolean'
    || typeof value === 'bigint'
  ) {
    return String(value);
  }
  if (value instanceof Date) return value.toISOString();
  return '';
}

/**
 * Converts a date-like value into a string for date matching.
 * @param value - Value to stringify
 * @returns Date string or empty string when not supported
 */
function stringifyDateValue(value: unknown): string {
  if (value === null || value === undefined) return '';
  if (value instanceof Date) return value.toISOString();
  if (typeof value === 'string') return value;
  if (
    typeof value === 'number'
    || typeof value === 'boolean'
    || typeof value === 'bigint'
  ) {
    return String(value);
  }
  return '';
}

/**
 * @param rows - Reactive rows reference
 * @param visibleColumns - Reactive visible columns
 * @param options - Filtering options
 * @returns Filtering state and helper actions
 */
export function useTableFiltering<T extends Record<string, unknown>>(
  rows: Ref<Array<T>>,
  visibleColumns: Ref<Array<TableColumn<T>>>,
  options: UseTableFilteringOptions = {},
) {
  const caseSensitiveByDefault = options.caseSensitiveByDefault ?? false;

  const filterStorage = reactive<FilterStateStorage>({
    byColumn: new Map(),
    allFilters: new Map(),
  });

  /**
   * @param key - Column key to read
   * @returns Filters stored for the column, if any
   */
  function getColumnFilters(key: string): Array<FilterState> | undefined {
    return filterStorage.byColumn.get(key);
  }

  /**
   * @param key - Column key to update
   * @param value - Filters to store for the column
   */
  function setColumnFilters(key: string, value: Array<FilterState>): void {
    filterStorage.byColumn.set(key, value);
  }

  /**
   * @param key - Column key to remove
   */
  function deleteColumnFilters(key: string): void {
    filterStorage.byColumn.delete(key);
  }

  /**
   * @param name - Column name
   * @returns The matching column definition, if found
   */
  function getColumnByName(name: string): TableColumn<T> | undefined {
    return visibleColumns.value.find(col => col.name === name);
  }

  /**
   * @param row - Row to read from
   * @param columnName - Column name to resolve
   * @returns Raw cell value for the column
   */
  function getRowValue(row: T, columnName: string): unknown {
    const column = getColumnByName(columnName);
    if (column === undefined) return undefined;

    if (typeof column.field === 'function') {
      return column.field(row);
    }
    return row[column.field];
  }

  /**
   * @param row - Row to evaluate
   * @param filter - Text filter definition
   * @returns True when the row matches the text filter
   */
  function matchesTextFilter(row: T, filter: TextFilter): boolean {
    const { value, columnName, caseSensitive } = filter;
    const isCaseSensitive = caseSensitive ?? caseSensitiveByDefault;

    if (value.trim() === '') return true;

    if (columnName === undefined) {
      return visibleColumns.value.some((col) => {
        const cellValue = getRowValue(row, col.name);
        return matchesSearchTerm(
          stringifyCellValue(cellValue),
          value,
          isCaseSensitive,
        );
      });
    }

    const cellValue = getRowValue(row, columnName);
    return matchesSearchTerm(
      stringifyCellValue(cellValue),
      value,
      isCaseSensitive,
    );
  }

  /**
   * @param row - Row to evaluate
   * @param filter - Date filter definition
   * @returns True when the row matches the date filter
   */
  function matchesDateFilter(row: T, filter: DateFilter): boolean {
    const { columnName, date, operator = 'equals' } = filter;
    const cellValue = getRowValue(row, columnName);

    if (cellValue === null || cellValue === undefined) return false;

    const dateValue = stringifyDateValue(cellValue);
    if (dateValue === '') return false;

    const isoDate = new Date(dateValue).toISOString();
    const [cellDate] = isoDate.split('T');
    if (cellDate === undefined) return false;
    const filterDate = date;

    switch (operator) {
      case 'equals': {
        return cellDate === filterDate;
      }
      case 'before': {
        return cellDate < filterDate;
      }
      case 'after': {
        return cellDate > filterDate;
      }
      case 'onOrBefore': {
        return cellDate <= filterDate;
      }
      case 'onOrAfter': {
        return cellDate >= filterDate;
      }
      default: {
        return true;
      }
    }
  }

  /**
   * @param row - Row to evaluate
   * @param filter - Date range filter definition
   * @returns True when the row matches the date range filter
   */
  function matchesDateRangeFilter(row: T, filter: DateRangeFilter): boolean {
    const { columnName, startDate, endDate } = filter;
    const cellValue = getRowValue(row, columnName);

    if (cellValue === null || cellValue === undefined) return false;

    const dateValue = stringifyDateValue(cellValue);
    if (dateValue === '') return false;

    const isoDate = new Date(dateValue).toISOString();
    const [cellDate] = isoDate.split('T');
    if (cellDate === undefined) return false;
    return cellDate >= startDate && cellDate <= endDate;
  }

  /**
   * @param row - Row to evaluate
   * @param filter - Custom filter definition
   * @returns True when the row matches the custom filter
   */
  function matchesCustomFilter(row: T, filter: CustomFilter): boolean {
    return filter.predicate(row);
  }

  /**
   * @param row - Row to evaluate
   * @param filter - Filter definition
   * @returns True when the row matches the filter
   */
  function matchesFilter(row: T, filter: FilterValue): boolean {
    switch (filter.type) {
      case 'text': {
        return matchesTextFilter(row, filter);
      }
      case 'date': {
        return matchesDateFilter(row, filter);
      }
      case 'dateRange': {
        return matchesDateRangeFilter(row, filter);
      }
      case 'custom': {
        return matchesCustomFilter(row, filter);
      }
      default: {
        return true;
      }
    }
  }

  /**
   * @param row - Row to evaluate
   * @returns True when the row matches all active filters
   */
  function matchesAllFilters(row: T): boolean {
    const allFilters: Array<FilterValue> = [];
    for (const columnFilters of filterStorage.byColumn.values()) {
      for (const filterState of columnFilters) {
        if (filterState.active) {
          allFilters.push(filterState.filter);
        }
      }
    }

    return allFilters.every(filter => matchesFilter(row, filter));
  }

  /**
   * @param key - Column key to initialize in storage
   */
  function initColumnStorage(key: string): void {
    if (getColumnFilters(key) === undefined) {
      setColumnFilters(key, []);
    }
  }

  /**
   * @param key - Column key to associate with the filter
   * @param filterValue - Filter definition to store
   */
  function addFilter(key: string, filterValue: FilterValue): void {
    const filterState: FilterState = {
      id: generateFilterId(),
      filter: filterValue,
      active: true,
      createdAt: Date.now(),
    };

    initColumnStorage(key);
    const columnFilters = getColumnFilters(key);
    if (columnFilters !== undefined) {
      columnFilters.push(filterState);
    }
    filterStorage.allFilters.set(filterState.id, filterState);
  }

  /**
   * @param columnName - Column to filter on (undefined = all columns)
   * @param searchText - Text to search for
   */
  function setTextFilter(
    columnName: string | undefined,
    searchText: string,
  ): void {
    if (columnName === undefined) {
      const globalFilters = getColumnFilters('');
      if (globalFilters !== undefined) {
        for (const f of globalFilters) filterStorage.allFilters.delete(f.id);
        deleteColumnFilters('');
      }
    }
    else {
      clearColumnFilters(columnName);
    }

    if (searchText.trim() !== '') {
      const filter: TextFilter = {
        type: 'text',
        value: searchText,
        columnName,
        caseSensitive: caseSensitiveByDefault,
      };
      addFilter(columnName ?? '', filter);
    }
  }

  /**
   * @param columnName - Column to filter on
   * @param date - Date string in YYYY-MM-DD format
   * @param operator - Comparison operator
   */
  function setDateFilter(
    columnName: string,
    date: string,
    operator:
      | 'equals'
      | 'before'
      | 'after'
      | 'onOrBefore'
      | 'onOrAfter' = 'equals',
  ): void {
    clearColumnFilters(columnName);

    const filter: DateFilter = {
      type: 'date',
      columnName,
      date,
      operator,
    };
    addFilter(columnName, filter);
  }

  /**
   * @param columnName - Column to filter on
   * @param startDate - Start date string in YYYY-MM-DD format
   * @param endDate - End date string in YYYY-MM-DD format
   */
  function setDateRangeFilter(
    columnName: string,
    startDate: string,
    endDate: string,
  ): void {
    clearColumnFilters(columnName);

    const filter: DateRangeFilter = {
      type: 'dateRange',
      columnName,
      startDate,
      endDate,
    };
    addFilter(columnName, filter);
  }

  /**
   * @param columnName - Column to filter on (undefined = global)
   * @param predicate - Filter predicate function
   */
  function setCustomFilter(
    columnName: string | undefined,
    predicate: (value: unknown, row?: T) => boolean,
  ): void {
    const key = columnName ?? '';
    clearColumnFilters(key);

    const filter: CustomFilter = {
      type: 'custom',
      columnName,
      predicate,
    };
    addFilter(key, filter);
  }

  /**
   * @param filterId - ID of filter to remove
   */
  function removeFilterById(filterId: string): void {
    const filterState = filterStorage.allFilters.get(filterId);
    if (filterState === undefined) return;

    const key = filterState.filter.columnName ?? '';
    const columnFilters = getColumnFilters(key);
    if (columnFilters !== undefined) {
      const index = columnFilters.findIndex(f => f.id === filterId);
      if (index !== -1) {
        columnFilters.splice(index, 1);
      }
      if (columnFilters.length === 0) {
        deleteColumnFilters(key);
      }
    }

    filterStorage.allFilters.delete(filterId);
  }

  /**
   * @param columnName - Column whose filters to clear
   */
  function clearColumnFilters(columnName: string): void {
    const columnFilters = getColumnFilters(columnName);
    if (columnFilters !== undefined) {
      for (const f of columnFilters) filterStorage.allFilters.delete(f.id);
      deleteColumnFilters(columnName);
    }
  }

  /**
   *
   */
  function clearAllFilters(): void {
    for (const key of filterStorage.byColumn.keys()) clearColumnFilters(key);
    filterStorage.allFilters.clear();
  }

  const filteredRows = computed(() =>
    rows.value.filter(row => matchesAllFilters(row)),
  );

  const activeFilters = computed<ActiveFiltersSummary>(() => {
    const byColumnEntries: Array<[string, Array<FilterValue>]> = [];
    const all: Array<FilterValue> = [];
    let count = 0;
    for (const [columnName, filterStates] of filterStorage.byColumn.entries()) {
      const activeFilterStates = filterStates.filter(f => f.active);
      if (activeFilterStates.length === 0) continue;

      const filters = activeFilterStates.map(f => f.filter);
      byColumnEntries.push([columnName, filters]);
      all.push(...filters);
      count += filters.length;
    }

    return {
      byColumn: Object.fromEntries(byColumnEntries),
      all,
      count,
    };
  });

  return {
    filteredRows,
    activeFilters,
    setTextFilter,
    setDateFilter,
    setDateRangeFilter,
    setCustomFilter,
    removeFilterById,
    clearColumnFilters,
    clearAllFilters,
  };
}

import { computed, type Ref } from 'vue';
import type { TableProperties } from './table.types';

/**
 * @param properties - Table properties
 * @param rows - Reactive rows reference
 * @returns Pagination state and helper methods
 */
export function useTablePagination<T extends Record<string, unknown>>(
  properties: TableProperties<T>,
  rows: Ref<Array<T>>,
) {
  const paginatedRows = computed(() => {
    if (properties.pagination === undefined) {
      return rows.value;
    }

    if (properties.pagination.rowsNumber !== undefined) {
      return rows.value;
    }

    const { page, rowsPerPage } = properties.pagination;
    if (rowsPerPage <= 0) return rows.value;

    const startIndex = (page - 1) * rowsPerPage;
    const endIndex = startIndex + rowsPerPage;

    return rows.value.slice(startIndex, endIndex);
  });

  const totalPages = computed(() => {
    if (properties.pagination === undefined) return 1;

    const { rowsPerPage, rowsNumber } = properties.pagination;
    const totalRows = rowsNumber ?? rows.value.length;

    return Math.ceil(totalRows / rowsPerPage);
  });

  /**
   * Navigate to a specific page.
   * @param page - Page number to navigate to
   * @returns Updated pagination object or undefined
   */
  function goToPage(page: number): typeof properties.pagination {
    if (properties.pagination === undefined) return undefined;

    return {
      ...properties.pagination,
      page: Math.max(1, Math.min(page, totalPages.value)),
    };
  }

  /**
   * Navigate to the next page.
   * @returns Updated pagination object or undefined
   */
  function nextPage(): typeof properties.pagination {
    if (properties.pagination === undefined) return undefined;
    return goToPage(properties.pagination.page + 1);
  }

  /**
   * Navigate to the previous page.
   * @returns Updated pagination object or undefined
   */
  function previousPage(): typeof properties.pagination {
    if (properties.pagination === undefined) return undefined;
    return goToPage(properties.pagination.page - 1);
  }

  /**
   * Change the number of rows displayed per page.
   * @param rowsPerPage - New rows per page value
   * @returns Updated pagination object or undefined
   */
  function changeRowsPerPage(
    rowsPerPage: number,
  ): typeof properties.pagination {
    if (properties.pagination === undefined) return undefined;

    return { ...properties.pagination, rowsPerPage, page: 1 };
  }

  return {
    paginatedRows,
    totalPages,
    goToPage,
    nextPage,
    prevPage: previousPage,
    changeRowsPerPage,
  };
}

import { computed, type Ref } from 'vue';
import type { TableProperties } from './table.types';

/**
 * @param properties - Table properties
 * @param rows - Reactive rows reference
 * @returns Row selection methods and computed properties
 */
export function useTableSelection<T extends Record<string, unknown>>(
  properties: TableProperties<T>,
  rows: Ref<Array<T>>,
) {
  /**
   * @param row - Row to resolve key for
   * @returns Row key value
   */
  function getRowKey(row: T): T[keyof T] {
    return row[properties.rowKey];
  }

  /**
   * @param row - Row to check
   * @returns True when the row is currently selected
   */
  function isRowSelected(row: T): boolean {
    if (
      properties.selected === undefined
      || properties.selected.length === 0
      || properties.selection === 'none'
    ) {
      return false;
    }

    const rowKey = getRowKey(row);
    return (properties.selected as Array<unknown>).includes(rowKey);
  }

  const allRowsSelected = computed(() => {
    if (
      properties.selected === undefined
      || properties.selection !== 'multiple'
      || rows.value.length === 0
    ) {
      return false;
    }

    return rows.value.every(row => isRowSelected(row));
  });

  const someRowsSelected = computed(() => {
    if (
      properties.selected === undefined
      || properties.selection !== 'multiple'
      || rows.value.length === 0
    ) {
      return false;
    }

    const selectedCount = rows.value.filter(row => isRowSelected(row)).length;
    return selectedCount > 0 && selectedCount < rows.value.length;
  });

  /**
   * @param row - Row to toggle
   * @returns Updated selected keys
   */
  function toggleRow(row: T): Array<T[keyof T]> {
    if (properties.selection === 'none') {
      return [];
    }

    const rowKey = getRowKey(row);
    const currentSelected = properties.selected ?? [];

    if (properties.selection === 'single') {
      return isRowSelected(row) ? [] : [rowKey];
    }

    return isRowSelected(row)
      ? currentSelected.filter(key => key !== rowKey)
      : [...currentSelected, rowKey];
  }

  /**
   * @returns Keys for all rows when selection is enabled
   */
  function selectAll(): Array<T[keyof T]> {
    if (properties.selection !== 'multiple') {
      return [];
    }

    return rows.value.map(row => getRowKey(row));
  }

  /**
   * @returns Empty selection list
   */
  function deselectAll(): Array<T[keyof T]> {
    return [];
  }

  /**
   * @returns Updated selected keys after toggle
   */
  function toggleAll(): Array<T[keyof T]> {
    if (properties.selection !== 'multiple') {
      return [];
    }

    return allRowsSelected.value ? deselectAll() : selectAll();
  }

  return {
    isRowSelected,
    allRowsSelected,
    someRowsSelected,
    toggleRow,
    selectAll,
    deselectAll,
    toggleAll,
  };
}

/**
 * UseTableSorting - Composable for table sorting logic
 *
 * Handles client-side and server-side sorting
 */

import { computed, type Ref } from 'vue';
import type { TableColumn, TableProperties } from './table.types';

/**
 * @param aValue - First value to compare
 * @param bValue - Second value to compare
 * @param descending - Whether to invert the result
 * @returns Comparison result compatible with Array.sort
 */
function compareSortValues(
  aValue: unknown,
  bValue: unknown,
  descending: boolean,
): number {
  if (aValue == null && bValue == null) return 0;
  if (aValue == null) return descending ? -1 : 1;
  if (bValue == null) return descending ? 1 : -1;

  if (aValue < bValue) return descending ? 1 : -1;
  if (aValue > bValue) return descending ? -1 : 1;
  return 0;
}

/**
 * @param properties - Table properties
 * @param rows - Reactive rows reference
 * @returns Sorted rows and sort toggle helper
 */
export function useTableSorting<T extends Record<string, unknown>>(
  properties: TableProperties<T>,
  rows: Ref<Array<T>>,
) {
  const sortedRows = computed(() => {
    if (
      properties.pagination?.sortBy == null
      || properties.pagination.sortBy === ''
    ) {
      return rows.value;
    }

    if (properties.clientSort !== true) {
      return rows.value;
    }

    const { sortBy, descending } = properties.pagination;

    const column = properties.columns.find(col => col.name === sortBy);
    if (column === undefined) {
      return rows.value;
    }

    if (properties.sortMethod !== undefined) {
      return properties.sortMethod(rows.value, sortBy, descending);
    }

    const sortedRowsCopy = [...rows.value];

    sortedRowsCopy.sort((a, b) => {
      const aValue = getColumnValue(a, column);
      const bValue = getColumnValue(b, column);

      return compareSortValues(aValue, bValue, descending);
    });

    return sortedRowsCopy;
  });

  /**
   * @param row - Row to read from
   * @param column - Column metadata
   * @returns The cell value for sorting
   */
  function getColumnValue(row: T, column: TableColumn<T>): unknown {
    if (typeof column.field === 'function') {
      return column.field(row);
    }

    return Reflect.get(row, column.field);
  }

  /**
   * @param columnName - Name of column to toggle sort on
   * @returns Updated pagination object or undefined
   */
  function toggleSort(
    columnName: string,
  ): typeof properties.pagination | undefined {
    if (properties.pagination === undefined) return;

    const column = properties.columns.find(
      (col: TableColumn<T>) => col.name === columnName,
    );
    if (column?.sortable !== true) return;

    const newPagination = { ...properties.pagination };

    if (newPagination.sortBy === columnName) {
      newPagination.descending = !newPagination.descending;
    }
    else {
      newPagination.sortBy = columnName;
      newPagination.descending = false;
    }

    newPagination.page = 1;

    return newPagination;
  }

  return {
    sortedRows,
    toggleSort,
  };
}

import { computed, type Ref } from 'vue';
import type { TableProperties, TableEmits } from './table.types';

import { useColumnResize } from './use-column-resize';
import { useTableFiltering } from './use-table-filtering';
import { useTablePagination } from './use-table-pagination';
import { useTableSelection } from './use-table-selection';
import { useTableSorting } from './use-table-sorting';
import { useVisibleColumns } from './use-visible-columns';

export interface UseTableStateOptions {
  caseSensitiveFilterByDefault?: boolean
}

/**
 * @param rows - Reactive rows
 * @param properties - Table properties
 * @param emit - Table emit function
 * @param options - Options
 * @returns Table state and helpers
 */
export function useTableState<T extends Record<string, unknown>>(
  rows: Ref<Array<T>> | Array<T>,
  properties: TableProperties<T>,
  emit: TableEmits<T>,
  options: UseTableStateOptions = {},
) {
  const rowsReference = Array.isArray(rows) ? computed(() => rows) : rows;

  const { visibleColumns } = useVisibleColumns(properties);

  const filteringState = useTableFiltering(rowsReference, visibleColumns, {
    caseSensitiveByDefault: options.caseSensitiveFilterByDefault ?? false,
  });

  const { sortedRows, toggleSort } = useTableSorting(
    properties,
    filteringState.filteredRows,
  );

  const {
    paginatedRows,
    totalPages,
    nextPage,
    prevPage,
    goToPage,
    changeRowsPerPage,
  } = useTablePagination(properties, sortedRows);

  const {
    isRowSelected,
    allRowsSelected,
    someRowsSelected,
    toggleRow,
    toggleAll,
  } = useTableSelection(properties, filteringState.filteredRows);

  const { startResize, getColumnStyle } = useColumnResize(properties, emit);

  const filteredRowCount = computed(
    () => filteringState.filteredRows.value.length,
  );

  const paginationInfo = computed(() => {
    if (properties.pagination === undefined)
      return { start: 0, end: 0, total: 0 };

    const totalRows
      = properties.pagination.rowsNumber ?? filteredRowCount.value;
    const page = properties.pagination.page;
    const rowsPerPage = properties.pagination.rowsPerPage;

    const start = totalRows === 0 ? 0 : (page - 1) * rowsPerPage + 1;
    const end = Math.min(page * rowsPerPage, totalRows);

    return { start, end, total: totalRows };
  });

  const hasActiveFilters = computed(
    () => filteringState.activeFilters.value.count > 0,
  );

  const isSorted = computed(() => {
    const sortBy = properties.pagination?.sortBy;
    return sortBy !== undefined && sortBy !== null && sortBy !== '';
  });

  const hasSelection = computed(() => {
    const selected = properties.selected;
    return selected !== undefined && selected.length > 0;
  });

  return {
    visibleColumns,
    filteredRows: filteringState.filteredRows,
    sortedRows,
    paginatedRows,

    get renderedRows() {
      return paginatedRows.value;
    },

    paginationInfo,
    totalPages,
    filteredRowCount,
    hasActiveFilters,
    isSorted,
    hasSelection,

    setTextFilter: (columnName: string | undefined, searchText: string) => {
      filteringState.setTextFilter(columnName, searchText);
    },

    setDateFilter: filteringState.setDateFilter,
    setDateRangeFilter: filteringState.setDateRangeFilter,
    setCustomFilter: filteringState.setCustomFilter,
    removeFilterById: filteringState.removeFilterById,
    clearColumnFilters: filteringState.clearColumnFilters,

    clearAllFilters: () => {
      filteringState.clearAllFilters();
    },

    get activeFilters() {
      return filteringState.activeFilters.value;
    },

    get activeFilterCount() {
      return filteringState.activeFilters.value.count;
    },

    toggleSort: (columnName: string) => {
      const newPagination = toggleSort(columnName);
      if (newPagination !== undefined) emit('update:pagination', newPagination);
    },

    nextPage: () => {
      const newPagination = nextPage();
      if (newPagination !== undefined) emit('update:pagination', newPagination);
    },

    prevPage: () => {
      const newPagination = prevPage();
      if (newPagination !== undefined) emit('update:pagination', newPagination);
    },

    goToPage: (page: number) => {
      const newPagination = goToPage(page);
      if (newPagination !== undefined) emit('update:pagination', newPagination);
    },

    changeRowsPerPage: (rowsPerPage: number) => {
      const newPagination = changeRowsPerPage(rowsPerPage);
      if (newPagination !== undefined) emit('update:pagination', newPagination);
    },

    isRowSelected,

    get allRowsSelected() {
      return allRowsSelected.value;
    },

    get someRowsSelected() {
      return someRowsSelected.value;
    },

    toggleRow,
    toggleAll,
    startResize,
    getColumnStyle,
  };
}

export type UseTableStateReturn<
  T extends Record<string, unknown> = Record<string, unknown>,
> = ReturnType<typeof useTableState<T>>;

/**
 * UseVisibleColumns - Composable for column visibility and ordering
 */

import { computed } from 'vue';
import type { TableProperties, TableColumn } from './table.types';

/**
 * @param properties - Table properties
 * @returns Visible columns and column visibility helpers
 */
export function useVisibleColumns<T extends Record<string, unknown>>(
  properties: TableProperties<T>,
) {
  const visibleColumns = computed<Array<TableColumn<T>>>(() => {
    let cols = [...properties.columns];

    if (
      properties.visibleColumnNames !== undefined
      && properties.visibleColumnNames.length > 0
    ) {
      const names = properties.visibleColumnNames;
      cols = cols.filter(col => names.includes(col.name));
    }

    if (
      properties.columnOrder !== undefined
      && properties.columnOrder.length > 0
    ) {
      const orderMap = new Map(
        properties.columnOrder.map((name, index) => [name, index]),
      );

      cols.sort((a, b) => {
        const aOrder = orderMap.get(a.name) ?? Number.MAX_SAFE_INTEGER;
        const bOrder = orderMap.get(b.name) ?? Number.MAX_SAFE_INTEGER;
        return aOrder - bOrder;
      });
    }

    return cols;
  });

  /**
   * @param name - Column name
   * @returns The matching column definition, if found
   */
  function getColumn(name: string): TableColumn<T> | undefined {
    return visibleColumns.value.find(col => col.name === name);
  }

  /**
   * @param name - Column name
   * @returns True when the column is currently visible
   */
  function isColumnVisible(name: string): boolean {
    return visibleColumns.value.some(col => col.name === name);
  }

  return {
    visibleColumns,
    getColumn,
    isColumnVisible,
  };
}

