export const toastPlugin = {
  install: (app: App, options: ToastPluginOptions = {}): void => {
    const globalProperties = app.config.globalProperties as AppGlobalProperties;
    const $q: QuasarNotifyLike | undefined = options.$q ?? globalProperties.$q;

    if ($q === undefined || typeof $q.notify !== 'function') return;

    const toast: ToastApi = createToast($q);

    app.config.globalProperties.$toast = toast;
