import { createApp, h } from 'vue';
import type {
  QuasarNotifyLike,
  ToastApi,
  ToastOptions,
  ToastRenderProperties,
} from '../../../reusable-components/types/toast';
import toastComponent from './Toast.vue';

export type {
  QuasarNotifyLike,
  ToastApi,
  ToastOptions,
  ToastRenderProperties,
} from '../../../reusable-components/types/toast';

export const renderToastHtml = (properties: ToastRenderProperties): string => {
  if (typeof document === 'undefined') return '';

  const container = document.createElement('div');
  const app = createApp({
    render: () =>
      h(
        toastComponent as Parameters<typeof h>[0],
        properties as unknown as Record<string, unknown>,
      ),
  });

  app.mount(container);
  const html = container.innerHTML;
  app.unmount();

  return html;
};

export const showToast = (
  $q: QuasarNotifyLike,
  options: ToastOptions = {},
): void => {
  showToastInternal($q, options);
};

export const createToast = ($q: QuasarNotifyLike): ToastApi => {
  return {
    show: (options?: ToastOptions) => showToast($q, options ?? {}),
  };
};

interface ActiveToast {
  close: () => void
  toastId: string
}

const activeToastsByDedupeKey = new Map<string, ActiveToast>();

const showToastInternal = (
  $q: QuasarNotifyLike,
  options: ToastOptions,
): void => {
  if (typeof document === 'undefined') return;

  const {
    timeoutSeconds,
    position = 'bottom-right',
    title = '',
    message = '',
    icon = 'info',
    countdownLabel = 'This notification closes in',
    closable = true,
    group = 'mesx-toast',
    id,
    dedupeKey,
    dedupeStrategy = 'replace',
  } = options;

  const effectiveDedupeKey = dedupeKey ?? id;
  if (effectiveDedupeKey !== undefined && effectiveDedupeKey !== '') {
    const existing = activeToastsByDedupeKey.get(effectiveDedupeKey);
    if (existing !== undefined) {
      if (dedupeStrategy === 'ignore') return;
      existing.close();
      activeToastsByDedupeKey.delete(effectiveDedupeKey);
    }
  }

  const isSticky = timeoutSeconds === 0 || timeoutSeconds === null;
  const effectiveClosable = isSticky ? true : closable;

  const toastId
    = id !== undefined && id !== ''
      ? `mesx-toast-${id}`
      : `mesx-toast-${Math.random().toString(36).slice(2)}`;
  let remaining = isSticky ? 0 : Math.max(1, Math.floor(timeoutSeconds ?? 5));
  let intervalId: ReturnType<typeof setInterval> | undefined;
  let isClosed = false;
  let dismissFromNotify: (() => void) | undefined;

  const html = renderToastHtml({
    toastId,
    title,
    message,
    icon,
    countdownSeconds: isSticky ? undefined : remaining,
    countdownLabel,
    closable: effectiveClosable,
  });

  const cleanup = (): void => {
    document.removeEventListener('click', handleCloseClick);
    if (intervalId !== undefined) clearInterval(intervalId);

    if (effectiveDedupeKey !== undefined && effectiveDedupeKey !== '') {
      const active = activeToastsByDedupeKey.get(effectiveDedupeKey);
      if (active?.toastId === toastId) {
        activeToastsByDedupeKey.delete(effectiveDedupeKey);
      }
    }
  };

  const close = (): void => {
    if (isClosed) return;
    isClosed = true;

    if (dismissFromNotify !== undefined) {
      dismissFromNotify();
      return;
    }

    cleanup();
    const root = document.querySelector(`[data-mesx-toast-id="${toastId}"]`);
    if (root !== null) root.remove();
  };

  /**
   * @param event - The click event
   */
  function handleCloseClick(event: Event): void {
    const { target } = event;
    if (!(target instanceof Element)) return;

    const closeButton = target.closest('[data-mesx-toast-close]');
    if (closeButton === null) return;

    const root = closeButton.closest(`[data-mesx-toast-id="${toastId}"]`);
    if (root === null) return;

    close();
  }

  document.addEventListener('click', handleCloseClick);

  if (effectiveDedupeKey !== undefined && effectiveDedupeKey !== '') {
    activeToastsByDedupeKey.set(effectiveDedupeKey, { close, toastId });
  }

  type NotifyResult = (() => void) | { dismiss: () => void } | undefined;
  const notifyResult: NotifyResult = $q.notify({
    group,
    html: true,
    position,
    badgePosition: 'bottom-right',
    badgeClass: 'mesx-toast-notify-group-badge',
    timeout: isSticky ? 0 : remaining * 1000,
    message: html,
    onDismiss: () => {
      cleanup();
    },
  }) as NotifyResult;

  if (typeof notifyResult === 'function') {
    dismissFromNotify = notifyResult;
  }
  else if (
    notifyResult !== undefined
    && typeof (notifyResult as { dismiss: () => void }).dismiss === 'function'
  ) {
    dismissFromNotify = () => {
      (notifyResult as { dismiss: () => void }).dismiss();
    };
  }

  if (!isSticky) {
    intervalId = setInterval(() => {
      remaining -= 1;
      const element = document.querySelector(
        `[data-mesx-toast-id="${toastId}"] [data-mesx-toast-countdown]`,
      );
      if (element !== null)
        element.textContent = String(Math.max(0, remaining));
      if (remaining <= 0) {
        clearInterval(intervalId);
      }
    }, 1000);
  }
};

import { ref, computed } from 'vue';
import type { AlertVariant, AlertAction } from './alert.types';

export interface Alert {
  id: string
  variant: AlertVariant
  title: string
  body?: string
  actions?: Array<AlertAction>
  dismissible: boolean
}

export interface AlertOptions {
  variant: AlertVariant
  title: string
  body?: string
  actions?: Array<AlertAction>
  dismissible?: boolean
}

const alertsReference = ref<Array<Alert>>([]);

/**
 * Shows an alert with the provided options.
 * @param options - Alert configuration
 * @returns Alert ID for dismissing the alert
 */
function show(options: AlertOptions): string {
  const id = `alert-${Date.now()}-${Math.random()}`;
  const alert: Alert = {
    id,
    variant: options.variant,
    title: options.title,
    body: options.body,
    actions: options.actions,
    dismissible: options.dismissible ?? true,
  };

  alertsReference.value.push(alert);
  return id;
}

/**
 * Dismisses an alert by ID.
 * @param alertId - Alert ID to dismiss
 */
function dismiss(alertId: string): void {
  alertsReference.value = alertsReference.value.filter(a => a.id !== alertId);
}

/**
 * Dismisses all active alerts.
 */
function dismissAll(): void {
  alertsReference.value = [];
}

/**
 * Composable for managing and displaying alerts.
 * @returns Alert management methods and computed properties
 */
export function useAlert() {
  return {
    show,
    success: (
      title: string,
      options?: Omit<AlertOptions, 'variant' | 'title'>,
    ) => show({ variant: 'success', title, ...options }),
    error: (title: string, options?: Omit<AlertOptions, 'variant' | 'title'>) =>
      show({ variant: 'error', title, ...options }),
    warning: (
      title: string,
      options?: Omit<AlertOptions, 'variant' | 'title'>,
    ) => show({ variant: 'warning', title, ...options }),
    info: (title: string, options?: Omit<AlertOptions, 'variant' | 'title'>) =>
      show({ variant: 'info', title, ...options }),

    alerts: computed(() => alertsReference.value),
    dismiss,
    dismissAll,
  };
}

