import { ref, computed } from 'vue';
import { en } from './locales/en';
import { fr } from './locales/fr';

type Locale = 'en' | 'fr';
type LocaleDict = Record<string, string>;

const locales: Record<Locale, LocaleDict> = { en, fr };

const currentLocale = ref<Locale>('en');

/**
 * @param locale - The locale code to set (e.g. 'en', 'fr')
 */
export function setLocale(locale: string): void {
  const key = locale.toLowerCase() as Locale;
  if (key in locales) currentLocale.value = key;
}

/**
 * @returns The current locale code
 */
export function getLocale(): string {
  return currentLocale.value;
}

/**
 * Translates a key to the current locale.
 * @param key - Translation key
 * @param parameters - Optional parameter substitutions
 * @returns Translated string
 */
function translate(
  key: string,
  parameters?: Record<string, string | number>,
): string {
  const dict: LocaleDict = locales[currentLocale.value] ?? locales.en;
  const dictValue = getLocaleValue(dict, key);
  const fallbackValue = getLocaleValue(locales.en, key);
  let translatedString: string = dictValue ?? fallbackValue ?? key;
  if (parameters !== undefined) {
    for (const [k, v] of Object.entries(parameters)) {
      translatedString = translatedString.replace(`{${k}}`, String(v));
    }
  }
  return translatedString;
}

/**
 * @param dict - Locale dictionary to read from
 * @param key - Translation key
 * @returns Resolved translation for the key, if present
 */
function getLocaleValue(dict: LocaleDict, key: string): string | undefined {
  const entry = Object.entries(dict).find(([k]) => k === key);
  return entry?.[1];
}

const translateFn = (
  key: string,
  parameters?: Record<string, string | number>,
) => translate(key, parameters);

/**
 * @returns An object with a `t` translation function
 */
export function useTranslation(): {
  t: (key: string, parameters?: Record<string, string | number>) => string
} {
  const t = computed(() => translateFn);
  return { t: t.value };
}

