import type { App } from 'vue';
import { setLocale } from './i18n';
import tokensCSS from './tokens.css?inline';

export interface MesxDesignSystemOptions {
  locale?: string
}

export const MESX_DESIGN_SYSTEM = {
  install(_app: App, options: MesxDesignSystemOptions = {}): void {
    if (options.locale !== undefined && options.locale !== '') {
      setLocale(options.locale);
    }

    if (
      typeof document !== 'undefined'
      && document.querySelector('#mesx-tokens') === null
    ) {
      const style = document.createElement('style');
      style.id = 'mesx-tokens';
      style.textContent = tokensCSS;
      document.head.prepend(style);
    }
  },
};

export { MESX_DESIGN_SYSTEM as MesxDesignSystem };

